class Solution {
    public double equalizeWater(int[] buckets, int loss) {
        double lo = 0, hi = 100000, keep = (100 - loss) / 100.0;
        for (int iter = 0; iter < 100; iter++) {
            double mid = (lo + hi) / 2, give = 0, need = 0;
            for (int b : buckets) {
                if (b > mid) give += b - mid;
                else need += mid - b;
            }
            if (give * keep >= need) lo = mid;
            else hi = mid;
        }
        return lo;
    }
}
